<?php
 require_once(__DIR__ . '/../../../init.php'); require_once('dicom/Dicom.php'); class med_common_dicom_viewer { private $db; public function getOpenViewerParams ($params) { $db = $this->db ?: $this->db = connectDb(); $ret = new stdClass(); $ret->success = false; try { if ($params->viewer === 'generic') { $ret->url = $this->makeUrlGenericViewer( $params->studyInstanceUid ); } else if ($params->viewer === 'osimis') { $ret->url = $this->makeUrlOsimisViewer( $this->lookupOrthancStudyId($params->pacsId, $params->studyInstanceUid) ); } else { $ret->message = "Неизвестный внутренний просмотрщик \"$params->viewer\""; return $ret; } $ret->success = true; return $ret; } catch (Throwable $e) { $ret->message = $e->getMessage(); return $ret; } } private function lookupOrthancStudyId ($pacsId, $studyInstanceUid) { $db = $this->db ?: $this->db = connectDb(); $pacs = selectSql($db, 'select host, httpport from DicomPacs where DicomPacsCode = ?', [$pacsId], PDO::FETCH_OBJ); if (empty($pacs)) { throw new Exception("В базе не найден PACS с первичным ключеч \"$pacsId\""); } $pacs = $pacs[0]; $url = "http://{$pacs->host}:{$pacs->httpport}/tools/lookup"; $res = httpPOST((object)[ 'url' => $url, 'headers' => ['Content-Type' => 'text/plain'], 'request_content' => $studyInstanceUid ]); if (empty($res)) { $ecode = httpError(); $estr = httpErrorStr(); throw new Exception("Ошибка HTTP запроса к PACS \"$url\" [$ecode - $estr]"); } $body = safe_json_decode($res['body']); if (empty($body) || !is_array($body)) { throw new Exception("В PACS не найдено ID исследования \"$studyInstanceUid\""); } return $body[0]->ID; } private function makeUrlOsimisViewer ($studyId) { return $_SERVER['HTTP_ORIGIN'] . "/pacs/orthanc/osimis-viewer/app/index.html?study=$studyId"; } private function makeUrlGenericViewer ($instanceId) { $viewerUrl = $this->getSettingsValue('dicomViewerUrl'); if (empty($viewerUrl)) { throw new Exception("Не настроена ссылка к вьюверу DICOM (dicomViewerUrl)."); } return str_replace('{studyInstanceId}', $instanceId, $viewerUrl); } private function getSettingsValue($key, $defaultValue = null) { $appConfig = getSessionValue('appConfig'); return isset($appConfig[$key]) ? $appConfig[$key] : $defaultValue; } } handleJsonRpc('med_common_dicom_viewer'); 